import { gsap } from 'gsap';
import { SplitText } from 'gsap/SplitText.js';

/*
  TextAnim : animations de texte aux couleurs du site (noir + violet néon #A855F7).

  Effets (data-anim="...") :
    neon    Les lettres s'allument comme un tube néon (halo violet qui se calme).      → défaut des h1 / h2
    sweep   Un faisceau de lumière violet balaie le texte et le révèle.                → défaut des h3 → h6
    rise    Fondu en montée, ligne par ligne (idéal pour les paragraphes).             → défaut du reste
    decode  Les lettres défilent en caractères violets puis se verrouillent.           → à utiliser à la main
    drift / orbit / nebula   Les anciens effets sont conservés.

  Autres attributs : data-repeat (rejoue à chaque passage), data-float (apesanteur douce des lettres).
*/

const PURPLE = '168, 85, 247';
const GLOW_STRONG = `0 0 18px rgba(${PURPLE}, 0.95), 0 0 42px rgba(${PURPLE}, 0.65)`;
const GLOW_SOFT = `0 0 14px rgba(${PURPLE}, 0.35)`;
const GLYPHS = '01<>/\\|[]{}#$%&*+=?';
const randomGlyph = () => GLYPHS[(Math.random() * GLYPHS.length) | 0];

const ANIMS = {
  // Le texte s'allume comme un néon
  neon: {
    target: 'chars',
    from: () => ({
      y: gsap.utils.random(6, 14),
      scale: 1.18,
      filter: 'blur(10px)',
      color: '#d8b4fe',
      textShadow: GLOW_STRONG,
      autoAlpha: 0,
    }),
    to: (ctx) => ({ color: ctx.baseColor, textShadow: GLOW_SOFT }),
    duration: 1.2,
    stagger: { each: 0.04, from: 'start' },
    ease: 'power3.out',
  },

  // Fondu en montée, ligne par ligne
  rise: {
    target: 'lines',
    from: () => ({ y: 22, filter: 'blur(6px)', autoAlpha: 0 }),
    duration: 0.9,
    stagger: { each: 0.12, from: 'start' },
    ease: 'power3.out',
  },

  // Faisceau de lumière qui révèle le texte (géré par sweep())
  sweep: { mode: 'sweep' },

  // Décodage : caractères violets qui se verrouillent (géré par decode())
  decode: { mode: 'decode' },

  // ----- Anciens effets -----

  // Débris qui flottent depuis des directions aléatoires
  drift: {
    target: 'chars',
    from: () => ({
      x: gsap.utils.random(-60, 60),
      y: gsap.utils.random(-40, 40),
      rotation: gsap.utils.random(-25, 25),
      filter: 'blur(8px)',
      autoAlpha: 0,
    }),
    duration: 2.4,
    stagger: { each: 0.06, from: 'random' },
    ease: 'sine.out',
  },

  // Bascule 3D depuis la profondeur
  orbit: {
    target: 'chars',
    from: () => ({
      z: -400,
      rotationY: gsap.utils.random(-90, 90),
      rotationX: gsap.utils.random(-40, 40),
      filter: 'blur(6px)',
      autoAlpha: 0,
    }),
    duration: 2.8,
    stagger: { each: 0.08, from: 'center' },
    ease: 'expo.out',
  },

  // Émerge d'un halo lumineux (maintenant violet)
  nebula: {
    target: 'chars',
    from: () => ({
      scale: gsap.utils.random(1.6, 2.4),
      y: gsap.utils.random(-10, 10),
      filter: 'blur(14px)',
      textShadow: `0 0 30px rgba(${PURPLE}, 0.9)`,
      autoAlpha: 0,
    }),
    to: { textShadow: `0 0 0px rgba(${PURPLE}, 0)` },
    duration: 3,
    stagger: { each: 0.07, from: 'edges' },
    ease: 'power2.out',
  },
};

export default class textAnim {
  constructor(element) {
    gsap.registerPlugin(SplitText);
    this.element = element;
    this.options = {
      repeat: false,
      float: false,
      type: 'neon',
    };
    this.isIn = false;
    this.tl = null;
    this.floatTweens = [];
    this.reduced =
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;

    document.fonts.ready.then(this.init.bind(this));
  }

  init() {
    this.setOptions();
    this.config = ANIMS[this.options.type] || ANIMS.neon;
    this.mode = this.config.mode || 'target';
    this.baseColor = getComputedStyle(this.element).color;
    gsap.set(this.element, { perspective: 800 });

    if (this.mode === 'sweep') this.createBeam();

    this.split = SplitText.create(this.element, {
      type: 'chars, words, lines',
      autoSplit: true,
      onSplit: (self) => this.applyRestState(self),
    });
    this.initObserver();
  }

  /* ---------- État de repos (avant / après animation) ---------- */

  applyRestState(self) {
    const visible = this.isIn || this.reduced;

    if (this.mode === 'sweep') {
      // Le SplitText peut avoir reconstruit le contenu : on remet le faisceau
      if (this.beam && !this.beam.isConnected)
        this.element.appendChild(this.beam);
      gsap.set(self.chars, { autoAlpha: 1 });
      this.element.style.clipPath = visible ? '' : 'inset(0 100% 0 0)';
      return;
    }
    if (this.config.target === 'lines') {
      gsap.set(self.chars, { autoAlpha: 1 });
      gsap.set(self.lines, { autoAlpha: visible ? 1 : 0 });
      return;
    }
    gsap.set(self.chars, { autoAlpha: visible ? 1 : 0 });
  }

  /* ---------- Observation de l'écran ---------- */

  initObserver() {
    const observer = new IntersectionObserver(this.watch.bind(this), {
      rootMargin: '0px 0px 0px 0px',
    });
    const start = () => observer.observe(this.element);

    // Écran de chargement affiché : on attend qu'il se dissolve pour lancer l'animation
    if (document.documentElement.classList.contains('is-loading')) {
      window.addEventListener('preloader:done', start, { once: true });
    } else {
      start();
    }
  }

  watch(entries, observer) {
    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      const target = entry.target;
      if (entry.isIntersecting) {
        this.anim(true);
        if (!this.options.repeat) observer.unobserve(target);
      } else {
        this.anim(false);
      }
    }
  }

  /* ---------- Apesanteur (option data-float) ---------- */

  startFloat() {
    this.stopFloat();
    this.floatTweens = this.split.chars.map((char) =>
      gsap.to(char, {
        y: gsap.utils.random(-4, 4),
        x: gsap.utils.random(-2, 2),
        rotation: gsap.utils.random(-3, 3),
        duration: gsap.utils.random(3, 6),
        ease: 'sine.inOut',
        repeat: -1,
        yoyo: true,
        delay: gsap.utils.random(0, 2),
      }),
    );
  }

  stopFloat() {
    this.floatTweens.forEach((t) => t.kill());
    this.floatTweens = [];
  }

  /* ---------- Animation principale ---------- */

  anim(isAnimIn) {
    this.isIn = isAnimIn;
    if (this.tl) this.tl.kill();
    this.stopFloat();
    this.restoreDecode();

    if (this.reduced) {
      this.showAll();
      return;
    }

    if (this.mode === 'sweep') return this.sweep(isAnimIn);
    if (this.mode === 'decode') return this.decode(isAnimIn);
    return this.animTargets(isAnimIn);
  }

  // Prefers-reduced-motion : le texte est simplement affiché
  showAll() {
    gsap.set([...this.split.chars, ...this.split.lines], {
      autoAlpha: 1,
      clearProps: 'filter,transform',
    });
    this.element.style.clipPath = '';
    if (this.beam) this.beam.style.opacity = '0';
  }

  // neon, rise, drift, orbit, nebula : lettres ou lignes
  animTargets(isAnimIn) {
    const targets =
      this.config.target === 'lines' ? this.split.lines : this.split.chars;
    const { from, duration, stagger, ease } = this.config;
    const to =
      typeof this.config.to === 'function'
        ? this.config.to(this)
        : this.config.to || {};

    if (isAnimIn) {
      this.tl = gsap.timeline({ delay: 0.25 });
      targets.forEach((t) => gsap.set(t, from()));
      this.tl.to(targets, {
        x: 0,
        y: 0,
        z: 0,
        scale: 1,
        rotation: 0,
        rotationX: 0,
        rotationY: 0,
        filter: 'blur(0px)',
        autoAlpha: 1,
        ...to,
        duration,
        stagger,
        ease,
      });
      if (this.options.float && this.config.target !== 'lines') {
        this.tl.call(() => this.startFloat());
      }
    } else {
      // Le texte repart doucement dans le vide
      this.tl = gsap.timeline();
      this.tl.to(targets, {
        x: () => gsap.utils.random(-30, 30),
        y: () => gsap.utils.random(-30, 30),
        rotation: () => gsap.utils.random(-15, 15),
        filter: 'blur(8px)',
        autoAlpha: 0,
        duration: 1.2,
        stagger: { each: 0.02, from: 'random' },
        ease: 'sine.in',
      });
    }
  }

  /* ---------- Effet « sweep » : faisceau de lumière ---------- */

  createBeam() {
    if (getComputedStyle(this.element).position === 'static') {
      this.element.style.position = 'relative';
    }
    const beam = document.createElement('span');
    beam.setAttribute('aria-hidden', 'true');
    beam.style.cssText = [
      'position:absolute',
      'top:-6px',
      'bottom:-6px',
      'left:0',
      'width:2px',
      'border-radius:2px',
      'pointer-events:none',
      'opacity:0',
      'background:linear-gradient(180deg, transparent, #f5e9ff 20%, #f5e9ff 80%, transparent)',
      `box-shadow:0 0 10px 2px rgba(${PURPLE}, 0.9), 0 0 36px 10px rgba(${PURPLE}, 0.55)`,
    ].join(';');
    this.beam = beam;
    this.element.appendChild(beam);
  }

  sweep(isAnimIn) {
    const el = this.element;
    const beam = this.beam;
    if (beam && !beam.isConnected) el.appendChild(beam);

    // Étendue réelle du texte (pas la largeur du bloc)
    const box = el.getBoundingClientRect();
    let minL = Infinity;
    let maxR = -Infinity;
    this.split.chars.forEach((c) => {
      const r = c.getBoundingClientRect();
      if (!r.width) return;
      minL = Math.min(minL, r.left - box.left);
      maxR = Math.max(maxR, r.right - box.left);
    });
    if (!Number.isFinite(minL)) {
      minL = 0;
      maxR = box.width;
    }
    const w = box.width;
    const start = Math.max(0, minL - 8);
    const end = Math.min(w, maxR + 8);
    const p = { x: isAnimIn ? start : end };

    const apply = () => {
      el.style.clipPath = `inset(-14px ${Math.max(0, w - p.x)}px -14px -14px)`;
      if (beam) beam.style.left = `${p.x}px`;
    };
    apply();

    if (isAnimIn) {
      this.tl = gsap.timeline({ delay: 0.25 });
      this.tl
        .set(beam, { opacity: 1 })
        .to(
          p,
          { x: end, duration: 1.1, ease: 'power2.inOut', onUpdate: apply },
          0,
        )
        // Les lettres arrivent éclairées, puis le halo se calme
        .fromTo(
          this.split.chars,
          { color: '#e9d5ff', textShadow: GLOW_STRONG },
          {
            color: this.baseColor,
            textShadow: GLOW_SOFT,
            duration: 0.9,
            stagger: { amount: 0.9, from: 'start' },
            ease: 'power2.out',
          },
          0.1,
        )
        .to(beam, { opacity: 0, duration: 0.25 }, '-=0.35')
        .add(() => {
          el.style.clipPath = '';
        });
    } else {
      this.tl = gsap.timeline();
      this.tl
        .set(beam, { opacity: 1 })
        .to(p, { x: start, duration: 0.6, ease: 'power2.in', onUpdate: apply })
        .to(beam, { opacity: 0, duration: 0.2 }, '-=0.2')
        .add(() => {
          el.style.clipPath = 'inset(0 100% 0 0)';
        });
    }
  }

  /* ---------- Effet « decode » : caractères qui se verrouillent ---------- */

  decode(isAnimIn) {
    const chars = this.split.chars;

    if (!isAnimIn) {
      this.tl = gsap.timeline();
      this.tl.to(chars, {
        filter: 'blur(6px)',
        autoAlpha: 0,
        duration: 0.5,
        stagger: { each: 0.01, from: 'random' },
        ease: 'sine.in',
      });
      return;
    }

    this.tl = gsap.timeline({ delay: 0.2 });
    chars.forEach((c, i) => {
      const orig = c.dataset.orig ?? (c.dataset.orig = c.textContent);
      if (!orig.trim()) {
        gsap.set(c, { autoAlpha: 1 });
        return;
      }
      const width = c.getBoundingClientRect().width;
      const st = { t: 0 };
      let last = 0;
      const startAt = i * 0.045 + Math.random() * 0.15;

      this.tl.to(
        st,
        {
          t: 1,
          duration: 0.45 + Math.random() * 0.45,
          ease: 'none',
          onStart: () => {
            c.style.width = `${width}px`;
            c.style.textAlign = 'center';
            c.textContent = randomGlyph();
            gsap.set(c, {
              autoAlpha: 1,
              filter: 'blur(0px)',
              color: `rgb(${PURPLE})`,
              textShadow: GLOW_STRONG,
            });
          },
          onUpdate: () => {
            const now = performance.now();
            if (st.t < 1 && now - last > 55) {
              c.textContent = randomGlyph();
              last = now;
            }
          },
          onComplete: () => {
            c.textContent = orig;
            c.style.width = '';
            c.style.textAlign = '';
            gsap.fromTo(
              c,
              { color: '#ffffff', textShadow: GLOW_STRONG },
              {
                color: this.baseColor,
                textShadow: GLOW_SOFT,
                duration: 0.7,
                ease: 'power2.out',
              },
            );
          },
        },
        startAt,
      );
    });
  }

  // Si l'animation est interrompue en plein défilement, on remet les vraies lettres
  restoreDecode() {
    if (this.mode !== 'decode' || !this.split) return;
    this.split.chars.forEach((c) => {
      if (c.dataset.orig !== undefined) {
        c.textContent = c.dataset.orig;
        c.style.width = '';
        c.style.textAlign = '';
      }
    });
  }

  /* ---------- Options ---------- */

  setOptions() {
    const { dataset, tagName } = this.element;
    if ('repeat' in dataset) this.options.repeat = true;
    if ('float' in dataset) this.options.float = true;

    // Effet par défaut selon la balise : titres → néon, sous-titres → faisceau, texte → montée
    const auto = /^H[12]$/.test(tagName)
      ? 'neon'
      : /^H[3-6]$/.test(tagName)
        ? 'sweep'
        : 'rise';
    this.options.type =
      dataset.anim && ANIMS[dataset.anim] ? dataset.anim : auto;
  }
}
