import { Renderer, Program, Mesh, Triangle, Color } from 'ogl';

/*
  Port JS natif du composant SpecularButton (React Bits), adapté au portfolio :
  - s'applique via data-component="SpecularButton" sur un <button> ou un <a>
    (son contenu devient le libellé) ;
  - les options se règlent avec des data-attributs, comme FlexCarousel ;
  - le rendu WebGL est mis en pause quand le bouton n'est pas visible à l'écran
    (utile pour les boutons cachés dans les .card_content du carrousel).

  Options (data-*) :
  data-size ("sm" | "md" | "lg" | "none"), data-radius, data-tint, data-tint-opacity,
  data-blur, data-text-color, data-line-color, data-base-color, data-intensity,
  data-shine-size, data-shine-fade, data-thickness, data-speed, data-follow-mouse,
  data-proximity, data-auto-animate
*/

// Marge du canvas autour du bouton, pour que la lueur déborde du bord
const PAD = 20;

const VERT = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const FRAG = `#version 300 es
precision highp float;

uniform vec2 uCenter;
uniform vec2 uHalfSize;
uniform float uRadius;
uniform float uAngle;
uniform float uPx;
uniform vec3 uLineColor;
uniform vec3 uBaseColor;
uniform float uIntensity;
uniform float uShineSize;
uniform float uShineFade;
uniform float uThickness;
uniform float uBaseWidth;

out vec4 fragColor;

float sdRoundedRect(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

float gaussianLine(float d, float sigma) {
  float x = d / (sigma + 1e-6);
  float k = mix(1.0, 1.6, smoothstep(0.0, 1.5, x));
  return exp(-k * x * x);
}

void main() {
  vec2 p = gl_FragCoord.xy - uCenter;
  float d = sdRoundedRect(p, uHalfSize, uRadius);
  vec2 L = vec2(cos(uAngle), sin(uAngle));

  // Trait de base sombre qui suit le bord
  float base = (1.0 - smoothstep(0.0, uBaseWidth, abs(d))) * 0.45;

  // Reflet spéculaire symétrique : les bords face à la lumière et à l'opposé brillent
  vec2 nEll = normalize(p / (uHalfSize * uHalfSize) + 1e-6);
  float phi = acos(clamp(abs(dot(nEll, L)), 0.0, 1.0));
  float rim = 1.0 - smoothstep(uShineSize - uShineFade, uShineSize + uShineFade + 1e-4, phi);
  float line = gaussianLine(d, uThickness);
  float edgeClamp = 1.0 - smoothstep(0.5 * uPx, 3.0 * uPx, abs(d));
  float hi = line * rim * edgeClamp * uIntensity;

  vec3 col = uBaseColor * base + uLineColor * hi;
  float a = clamp(base + hi, 0.0, 1.0);
  fragColor = vec4(col, a);
}
`;

const DEFAULTS = {
  size: 'lg',
  radius: 18,
  tint: '#ffffff',
  tintOpacity: 0,
  blur: 0,
  textColor: '#f5f5f5',
  lineColor: '#ffffff',
  baseColor: '#525252',
  intensity: 1,
  shineSize: 10,
  shineFade: 40,
  thickness: 1,
  speed: 0.35,
  followMouse: true,
  proximity: 250,
  autoAnimate: false,
};

export default class SpecularButton {
  constructor(element) {
    this.el = element;
    if (!element || element.classList.contains('specular-button')) return;

    this.readOptions();
    this.buildDOM();

    // WebGL2 requis pour l'effet : sinon le bouton reste un bouton normal
    const probe = document.createElement('canvas').getContext('webgl2');
    if (!probe) {
      console.warn('SpecularButton : WebGL2 indisponible');
      return;
    }
    probe.getExtension('WEBGL_lose_context')?.loseContext();

    this.setup();
  }

  /* ---------- Lecture des options ---------- */

  readOptions() {
    const d = this.el.dataset;
    const num = (v, fallback) =>
      v === undefined || v === '' || Number.isNaN(parseFloat(v))
        ? fallback
        : parseFloat(v);
    const bool = (v, fallback) => (v === undefined ? fallback : v !== 'false');

    this.settings = {
      size: d.size || DEFAULTS.size,
      radius: num(d.radius, DEFAULTS.radius),
      tint: d.tint || DEFAULTS.tint,
      tintOpacity: num(d.tintOpacity, DEFAULTS.tintOpacity),
      blur: num(d.blur, DEFAULTS.blur),
      textColor: d.textColor || DEFAULTS.textColor,
      lineColor: d.lineColor || DEFAULTS.lineColor,
      baseColor: d.baseColor || DEFAULTS.baseColor,
      intensity: num(d.intensity, DEFAULTS.intensity),
      shineSize: num(d.shineSize, DEFAULTS.shineSize),
      shineFade: num(d.shineFade, DEFAULTS.shineFade),
      thickness: num(d.thickness, DEFAULTS.thickness),
      speed: num(d.speed, DEFAULTS.speed),
      followMouse: bool(d.followMouse, DEFAULTS.followMouse),
      proximity: num(d.proximity, DEFAULTS.proximity),
      // data-auto-animate sans valeur = activé
      autoAnimate:
        'autoAnimate' in d ? d.autoAnimate !== 'false' : DEFAULTS.autoAnimate,
    };
  }

  /* ---------- DOM : classes, variables CSS, calques ---------- */

  buildDOM() {
    const { el, settings: s } = this;

    el.classList.add('specular-button');
    if (s.size !== 'none') el.classList.add(`specular-button--${s.size}`);
    if (el.tagName === 'BUTTON' && !el.hasAttribute('type')) el.type = 'button';

    el.style.setProperty('--sb-radius', `${s.radius}px`);
    el.style.setProperty('--sb-tint', s.tint);
    el.style.setProperty('--sb-tint-opacity', s.tintOpacity);
    el.style.setProperty('--sb-blur', `${s.blur}px`);
    el.style.setProperty('--sb-text-color', s.textColor);

    // Le contenu existant devient le libellé, au-dessus du canvas
    this.label = document.createElement('span');
    this.label.className = 'specular-button__label';
    this.label.append(...el.childNodes);

    this.fx = document.createElement('span');
    this.fx.className = 'specular-button__fx';
    this.fx.setAttribute('aria-hidden', 'true');

    el.append(this.fx, this.label);
  }

  /* ---------- Moteur WebGL (port du composant React) ---------- */

  setup() {
    const btn = this.el;
    const fx = this.fx;
    const s = this.settings;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const renderer = new Renderer({
      alpha: true,
      premultipliedAlpha: true,
      antialias: true,
      dpr,
    });
    const gl = renderer.gl;
    if (!renderer.isWebgl2) {
      gl.getExtension('WEBGL_lose_context')?.loseContext();
      return;
    }
    gl.clearColor(0, 0, 0, 0);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

    const geometry = new Triangle(gl);
    if (geometry.attributes.uv) delete geometry.attributes.uv;

    const lineC = new Color(s.lineColor);
    const baseC = new Color(s.baseColor);

    const program = new Program(gl, {
      vertex: VERT,
      fragment: FRAG,
      uniforms: {
        uCenter: { value: [0, 0] },
        uHalfSize: { value: [1, 1] },
        uRadius: { value: 0 },
        uAngle: { value: 2.4 },
        uPx: { value: dpr },
        uLineColor: { value: [lineC.r, lineC.g, lineC.b] },
        uBaseColor: { value: [baseC.r, baseC.g, baseC.b] },
        uIntensity: { value: 0 },
        uShineSize: { value: (s.shineSize * Math.PI) / 180 },
        uShineFade: { value: (s.shineFade * Math.PI) / 180 },
        uThickness: { value: s.thickness * dpr },
        uBaseWidth: { value: dpr },
      },
    });

    const mesh = new Mesh(gl, { geometry, program });
    const canvas = gl.canvas;
    fx.append(canvas);

    const reducedMotion =
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;

    let w = 1;
    let h = 1;
    let radius = s.radius;
    const resize = (entries) => {
      // Taille de mise en page (sans les transform: scale des parents, ex. le focus du carrousel),
      // fractionnaire quand le ResizeObserver la fournit, pour que le contour colle au bord CSS
      const box = entries?.[0]?.borderBoxSize?.[0];
      w = box ? box.inlineSize : btn.offsetWidth;
      h = box ? box.blockSize : btn.offsetHeight;
      if (!w || !h) return;
      // Rayon réel du CSS (au cas où le SCSS du projet surcharge border-radius)
      const cssRadius = parseFloat(getComputedStyle(btn).borderTopLeftRadius);
      radius = Number.isNaN(cssRadius) ? s.radius : cssRadius;
      renderer.setSize(w + PAD * 2, h + PAD * 2);
      canvas.style.width = '100%';
      canvas.style.height = '100%';
      program.uniforms.uCenter.value = [
        (PAD + w / 2) * dpr,
        (PAD + h / 2) * dpr,
      ];
      program.uniforms.uHalfSize.value = [(w / 2) * dpr, (h / 2) * dpr];
      program.uniforms.uRadius.value =
        Math.min(radius, Math.min(w, h) / 2) * dpr;
      start();
    };

    // La lumière s'oriente vers le curseur (n'importe où sur la page)
    let pointerAngle = null;
    let proximityT = 0;
    const onPointerMove = (e) => {
      const rect = btn.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = Math.max(rect.left - e.clientX, 0, e.clientX - rect.right);
      const dy = Math.max(rect.top - e.clientY, 0, e.clientY - rect.bottom);
      const dist = Math.hypot(dx, dy);
      if (dist === 0) {
        // Sur le bouton : la lumière se pose en diagonale et ondule avec le curseur
        const nx = (e.clientX - cx) / (rect.width / 2);
        const ny = (cy - e.clientY) / (rect.height / 2);
        pointerAngle =
          Math.atan2(2 / rect.height, -2 / rect.width) + nx * 0.3 + ny * 0.15;
      } else {
        pointerAngle = Math.atan2(cy - e.clientY, e.clientX - cx);
      }
      const t = Math.max(0, 1 - dist / Math.max(s.proximity, 1));
      proximityT = t * t * (3 - 2 * t);
      start();
    };

    let angle = 2.4;
    let idleAngle = 2.4;
    let bright = 0;
    let last = performance.now();
    let raf = 0;
    let visible = false;
    let alive = true;

    const frame = (now) => {
      raf = 0;
      if (!alive || !visible) return;
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;

      if (!reducedMotion) idleAngle += s.speed * dt;
      const steer =
        s.followMouse &&
        pointerAngle != null &&
        (!s.autoAnimate || proximityT > 0);
      const target = steer ? pointerAngle : idleAngle;
      const diff = ((target - angle + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
      angle += diff * (1 - Math.exp(-dt * 7));

      // Le reflet apparaît avec la proximité du curseur, sauf si autoAnimate le garde allumé
      const brightTarget = s.autoAnimate ? 1 : proximityT;
      bright += (brightTarget - bright) * (1 - Math.exp(-dt * 8));

      program.uniforms.uAngle.value = angle;
      program.uniforms.uIntensity.value = s.intensity * bright;
      renderer.render({ scene: mesh });

      // On s'arrête quand tout est immobile (le reflet éteint ne bouge plus)
      const settled =
        !s.autoAnimate &&
        Math.abs(brightTarget - bright) < 0.001 &&
        (bright < 0.001 || (steer && Math.abs(diff) < 0.001));
      if (!settled) raf = requestAnimationFrame(frame);
    };

    const start = () => {
      if (raf || !visible || !alive) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(btn);
    // Pause quand le bouton est hors écran ou caché (display: none)
    const intersectionObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      start();
    });
    intersectionObserver.observe(btn);
    window.addEventListener('pointermove', onPointerMove, { passive: true });

    resize();

    this.destroy = () => {
      alive = false;
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
      canvas.remove();
    };
  }
}
