const GRADIENT_POSITIONS = [
  '80% 55%',
  '69% 34%',
  '8% 6%',
  '41% 38%',
  '86% 85%',
  '82% 18%',
  '51% 4%',
];
const GRADIENT_KEYS = [
  '--gradient-one',
  '--gradient-two',
  '--gradient-three',
  '--gradient-four',
  '--gradient-five',
  '--gradient-six',
  '--gradient-seven',
];
const COLOR_MAP = [0, 1, 2, 0, 1, 2, 1];

const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
const easeInCubic = (x) => x * x * x;

function animateValue({
  start = 0,
  end = 100,
  duration = 1000,
  delay = 0,
  ease = easeOutCubic,
  onUpdate,
  onEnd,
}) {
  const t0 = performance.now() + delay;
  const tick = () => {
    const t = Math.min((performance.now() - t0) / duration, 1);
    onUpdate(start + (end - start) * ease(t));
    if (t < 1) requestAnimationFrame(tick);
    else onEnd?.();
  };
  setTimeout(() => requestAnimationFrame(tick), delay);
}

export default class BorderGlow {
  constructor(element) {
    this.card = element;
    this.options = {
      edgeSensitivity: 30,
      glowColor: '40 80 80', // "H S L"
      backgroundColor: '#120F17',
      borderRadius: 28,
      glowRadius: 40,
      glowIntensity: 1,
      coneSpread: 25,
      fillOpacity: 0.5,
      animated: false,
      colors: ['#c084fc', '#f472b6', '#38bdf8'],
    };

    this.setOptions();
    this.build();
    this.card.addEventListener('pointermove', this.onMove.bind(this));
    if (this.options.animated) this.sweep();
  }

  // Options via data-attributes : data-edge-sensitivity, data-glow-color,
  // data-background-color, data-border-radius, data-glow-radius, data-glow-intensity,
  // data-cone-spread, data-fill-opacity, data-animated, data-colors="#aaa,#bbb,#ccc"
  setOptions() {
    const d = this.card.dataset;
    const o = this.options;
    if (d.edgeSensitivity) o.edgeSensitivity = parseFloat(d.edgeSensitivity);
    if (d.glowColor) o.glowColor = d.glowColor;
    if (d.backgroundColor) o.backgroundColor = d.backgroundColor;
    if (d.borderRadius) o.borderRadius = parseFloat(d.borderRadius);
    if (d.glowRadius) o.glowRadius = parseFloat(d.glowRadius);
    if (d.glowIntensity) o.glowIntensity = parseFloat(d.glowIntensity);
    if (d.coneSpread) o.coneSpread = parseFloat(d.coneSpread);
    if (d.fillOpacity) o.fillOpacity = parseFloat(d.fillOpacity);
    if ('animated' in d) o.animated = true;
    if (d.colors) o.colors = d.colors.split(',').map((c) => c.trim());
  }

  build() {
    const o = this.options;
    const card = this.card;

    card.classList.add('border-glow-card');
    if (this.isLight(o.backgroundColor))
      card.classList.add('border-glow-card--light');

    const vars = {
      '--card-bg': o.backgroundColor,
      '--edge-sensitivity': o.edgeSensitivity,
      '--border-radius': `${o.borderRadius}px`,
      '--glow-padding': `${o.glowRadius}px`,
      '--cone-spread': o.coneSpread,
      '--fill-opacity': o.fillOpacity,
      ...this.glowVars(),
      ...this.gradientVars(),
    };
    Object.entries(vars).forEach(([k, v]) => card.style.setProperty(k, v));

    // Structure attendue par le CSS : <span.edge-light> + <div.border-glow-inner>
    const edge = document.createElement('span');
    edge.className = 'edge-light';
    const inner = document.createElement('div');
    inner.className = 'border-glow-inner';
    inner.append(...card.childNodes);
    card.append(edge, inner);
  }

  glowVars() {
    const m = this.options.glowColor.match(
      /([\d.]+)\s*([\d.]+)%?\s*([\d.]+)%?/,
    );
    const [h, s, l] = m ? [m[1], m[2], m[3]] : [40, 80, 80];
    const opacities = [100, 60, 50, 40, 30, 20, 10];
    const keys = ['', '-60', '-50', '-40', '-30', '-20', '-10'];
    const vars = {};
    opacities.forEach((op, i) => {
      vars[`--glow-color${keys[i]}`] =
        `hsl(${h}deg ${s}% ${l}% / ${Math.min(op * this.options.glowIntensity, 100)}%)`;
    });
    return vars;
  }

  gradientVars() {
    const { colors } = this.options;
    const vars = {};
    for (let i = 0; i < 7; i++) {
      const c = colors[Math.min(COLOR_MAP[i], colors.length - 1)];
      vars[GRADIENT_KEYS[i]] =
        `radial-gradient(at ${GRADIENT_POSITIONS[i]}, ${c} 0px, transparent 50%)`;
    }
    vars['--gradient-base'] = `linear-gradient(${colors[0]} 0 100%)`;
    return vars;
  }

  isLight(color) {
    const v = color.trim().replace('#', '');
    if (!/^[\da-f]{3}([\da-f]{3})?$/i.test(v)) return false;
    const hex = v.length === 3 ? [...v].map((c) => c + c).join('') : v;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return r * 0.2126 + g * 0.7152 + b * 0.0722 > 180;
  }

  onMove(e) {
    const rect = this.card.getBoundingClientRect();
    const cx = rect.width / 2;
    const cy = rect.height / 2;
    const dx = e.clientX - rect.left - cx;
    const dy = e.clientY - rect.top - cy;

    // Proximité du bord (0 au centre, 1 au bord)
    const kx = dx !== 0 ? cx / Math.abs(dx) : Infinity;
    const ky = dy !== 0 ? cy / Math.abs(dy) : Infinity;
    const edge = Math.min(Math.max(1 / Math.min(kx, ky), 0), 1);

    let angle =
      dx === 0 && dy === 0 ? 0 : Math.atan2(dy, dx) * (180 / Math.PI) + 90;
    if (angle < 0) angle += 360;

    this.card.style.setProperty('--edge-proximity', (edge * 100).toFixed(3));
    this.card.style.setProperty('--cursor-angle', `${angle.toFixed(3)}deg`);
  }

  // Animation d'intro (data-animated)
  sweep() {
    const card = this.card;
    const a0 = 110;
    const a1 = 465;
    const setAngle = (v) =>
      card.style.setProperty(
        '--cursor-angle',
        `${(a1 - a0) * (v / 100) + a0}deg`,
      );

    card.classList.add('sweep-active');
    card.style.setProperty('--cursor-angle', `${a0}deg`);

    animateValue({
      duration: 500,
      onUpdate: (v) => card.style.setProperty('--edge-proximity', v),
    });
    animateValue({
      ease: easeInCubic,
      duration: 1500,
      end: 50,
      onUpdate: setAngle,
    });
    animateValue({
      delay: 1500,
      duration: 2250,
      start: 50,
      end: 100,
      onUpdate: setAngle,
    });
    animateValue({
      ease: easeInCubic,
      delay: 2500,
      duration: 1500,
      start: 100,
      end: 0,
      onUpdate: (v) => card.style.setProperty('--edge-proximity', v),
      onEnd: () => card.classList.remove('sweep-active'),
    });
  }
}
